.m03{width:360px;height:760px;box-sizing:border-box;display:flex;flex-direction:column;background:#F8F5FA;color:#493453;font-family:'Avenir Next','Helvetica Neue',sans-serif;font-size:14px;overflow:hidden} .m03 *{box-sizing:border-box} .m03 h1,.m03 h2,.m03 h3,.m03 p{margin:0} .m03 svg{display:block;flex-shrink:0} .m03 .st{height:30px;flex-shrink:0;padding:10px 23px 0;display:flex;justify-content:space-between;align-items:center;font-size:11px;font-weight:600} .m03 .signals{display:flex;align-items:center} .m03 .head{height:58px;flex-shrink:0;padding:8px 22px;display:flex;align-items:center;justify-content:space-between} .m03 .brand{display:flex;align-items:center;gap:8px;font-size:17px;font-weight:600;letter-spacing:-.5px} .m03 .muted{color:#8A778E} .m03 .nav{height:52px;flex-shrink:0;display:flex;justify-content:space-around;align-items:center;border-top:1px solid color-mix(in srgb,#493453 10%,transparent);background:#F8F5FA} .m03 .navitem{display:flex;align-items:center;justify-content:center;gap:5px;flex-direction:column;font-size:11px;color:#8A778E;min-width:80px} .m03 .navitem.on{color:#704278;font-weight:600} .m03 .gesture{height:16px;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#F8F5FA} .m03 .gesture i{display:block;width:105px;height:3px;border-radius:3px;background:#493453} .m03 .sect{display:flex;align-items:center;justify-content:space-between} .m03 .sect h2{font-size:17px;font-weight:600;letter-spacing:-.5px} .m03 .sect span{font-size:11px;color:#704278} .m03 .circle{width:35px;height:35px;border-radius:50%;display:grid;place-items:center}
.m03 .head{height:57px}.m03 .brand{font-size:19px;font-weight:500}.m03 .body{flex:1;min-height:0;padding:7px 22px 10px}.m03 h1{font:35px/1.09 'Ark Serif',Georgia,serif;letter-spacing:-1px;margin-bottom:17px}.m03 .tabs{height:39px;display:flex;border-bottom:1px solid #E2D9E6;margin-bottom:24px;gap:26px;font-size:12px;align-items:flex-start}.m03 .tabs span{height:39px;color:#8A778E}.m03 .tabs .sel{color:#493453;border-bottom:2px solid #704278;font-weight:600}.m03 .shelf{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:14px}.m03 .volume{height:155px;border-radius:3px 7px 7px 3px;position:relative;overflow:hidden;padding:13px 11px;display:flex;flex-direction:column;justify-content:space-between;border-left:4px solid #9A739D}.m03 .volume:after{content:'';position:absolute;inset:0 auto 0 4px;width:1px;background:#ffffff36}.m03 .volume b{font:19px/1.13 'Ark Serif',Georgia,serif;letter-spacing:-.3px}.m03 .volume small{font-size:11px}.m03 .v1{background:#D9E5D1;color:#35523E;border-left-color:#91AB82}.m03 .v2{background:#493453;color:#F3EAF6;border-left-color:#2B1934}.m03 .v3{background:#ECD6C9;color:#6C4037;border-left-color:#C79A80}.m03 .vmeta{font-size:11px;margin-top:9px;color:#8A778E;display:flex;align-items:center;gap:3px;white-space:nowrap}.m03 .shelfline{height:5px;background:#DCCFE0;margin:10px -6px 22px;border-radius:3px}.m03 .next{height:150px;margin-top:12px;background:#EBDFF0;border-radius:14px;padding:18px;display:flex;position:relative;overflow:hidden}.m03 .next h3{font:25px/1.05 'Ark Serif',Georgia,serif;width:170px;margin-bottom:9px;letter-spacing:-.5px}.m03 .next p{font-size:11px;line-height:1.55;width:172px;color:#7F6687}.m03 .next .add{font-size:11px;display:flex;align-items:center;gap:6px;margin-top:13px;font-weight:600}.m03 .medical{position:absolute;width:73px;height:106px;background:#B696BF;color:#F8F5FA;right:18px;top:24px;transform:rotate(7deg);border-radius:3px 7px 7px 3px;border-left:6px solid #96729F;display:flex;align-items:center;justify-content:center}.m03 .trust{font-size:11px;color:#8A778E;display:flex;gap:6px;align-items:center;justify-content:center;margin-top:17px}.m03 .nav{border-color:#E2D9E6}.m03 .navitem.on{color:#704278}.m03 .navitem.on svg{fill:#E2CEE8}

.m03 .tabs{margin-bottom:18px}.m03 .shelfline{margin-bottom:16px}.m03 .next{height:140px}.m03 .trust{margin-top:10px;font-size:11px}

.m03 .next{padding:14px}.m03 .next h3{font-size:23px;margin-bottom:7px}.m03 .next p{line-height:1.45}.m03 .next .add{margin-top:8px}.m03 .medical{top:17px}
